 function renderList(){if(!active())return;q('target').textContent=project?projectLabel||'当前项目':'请先选择一个项目';q('new').disabled=!opts?.can_save||!data;q('read').disabled=!project;for(const b of root.querySelectorAll('[data-cases-tab]'))b.setAttribute('aria-pressed',String(b.dataset.casesTab===tab));const rows=data?.items.filter(x=>x.kind===tab)??[];page=Math.min(page,Math.max(0,Math.ceil(rows.length/20)-1));q('pages').textContent=rows.length?'第 '+(page+1)+' 页，共 '+rows.length+' 项':'';q('prev').disabled=!data||page===0;q('next').disabled=!data||(page+1)*20>=rows.length;q('table').innerHTML=rows.length?'<table class="tbl"><thead><tr><th scope="col">事项</th><th scope="col">状态</th><th scope="col">已确认金额 / 当前余额</th><th scope="col">操作</th></tr></thead><tbody>'+rows.slice(page*20,page*20+20).map(r=>'<tr><td data-label="事项">'+esc(caseTitle(r))+'</td><td data-label="状态">'+esc(STATES[r.state])+' · 第 '+r.version+' 版</td><td data-label="已确认金额 / 当前余额">'+(r.financial.length?r.financial.map(f=>esc(teacherLabel(f.chain.teacher_id))+'：'+esc(f.chain.current_amount)+' 元 / '+esc(f.chain.balance)+' 元').join('<br>'):'尚未确认')+'</td><td data-label="操作"><button class="btn gray" type="button" data-cases-open="'+esc(r.case_code)+'">查看 / 办理</button></td></tr>').join('')+'</tbody></table>':'<div class="empty-state"><p>'+(!data?'请选择项目并读取当前事项。':'当前没有'+esc(KINDS[tab])+'事项。')+'</p></div>';for(const b of root.querySelectorAll('[data-cases-open]'))b.onclick=()=>open(b.dataset.casesOpen);}
