 async function refresh(projectId,label=''){if(!active())return false;if(session&&owns(session)){if(!beforeClose(session))return false;host.closeModal();}if(projectId!==null&&projectId!==undefined&&projectId!==''&&!pos(Number(projectId)))return false;project=projectId?Number(projectId):null;if(label)projectLabel=label;const ticket=++pageTicket;pageAbort?.abort();pageAbort=new AbortController();data=null;opts=null;renderList();q('notice').textContent=project?'正在读取当前项目事项…':'';if(!project)return true;try{const [a,b]=await projectRead(project,pageAbort.signal);if(!active()||ticket!==pageTicket)return false;data=a;opts=b;renderList();q('notice').textContent=b.can_save===true?'':'当前可查阅事项；新建权限以当前机构授权为准。';return true;}catch(e){if(active()&&ticket===pageTicket&&e?.name!=='AbortError'){data=null;opts=null;renderList();q('notice').textContent=[401,403].includes(errStatus(e))?'当前无权读取本项目课酬事项。':e?.message||'读取失败，请刷新。';}return false;}}
 const exact=v=>v===null||v===undefined?'待核实':String(v);
 const input=(s,path,label,type='text',values=null,disabled=false)=>{const v=get(s.draft,path),name=esc(path);return'<div class="form-item"><label>'+esc(label)+'</label>'+(values?'<select data-case-field="'+name+'"'+(disabled?' disabled':'')+'>'+Object.entries(values).map(([k,l])=>'<option value="'+esc(k)+'"'+(String(v??'')===k?' selected':'')+'>'+esc(l)+'</option>').join('')+'</select>':type==='textarea'?'<textarea rows="3" maxlength="2000" data-case-field="'+name+'"'+(disabled?' disabled':'')+'>'+esc(v??'')+'</textarea>':'<input type="'+type+'" '+(type==='text'?'maxlength="500" ':'')+'data-case-field="'+name+'" value="'+esc(v??'')+'"'+(disabled?' disabled':'')+'>')+'</div>';};
 const sel=(s,path,label,values,disabled=false)=>input(s,path,label,'text',{'':'待核实',...values},disabled),tri=(s,path,label)=>input(s,path,label,'text',TRUTH),proofFields=(s,prefix,label)=>input(s,prefix+'note',label+'说明','textarea')+input(s,prefix+'reference',label+'凭证号 / 资料位置（选填）');
 function pickerButton(s,path,label,type,locked=false){const value=get(s.draft,path);let display='尚未选择';if(type==='teacher'&&value)display=teacherLabel(value,s.options,s.teachers);if(type==='dispatch'&&value){const d=s.options.dispatches.find(x=>x.dispatch_id===value);display=d?d.teacher_name+' · '+(d.subject||'未填课题')+' · '+(d.teach_date||'日期待定'):'原授课记录当前不在选项中';}if(type==='chain'&&value){const c=s.options.financial_chains.find(x=>x.chain_code===value);display=c?teacherLabel(c.teacher_id,s.options,s.teachers)+' · '+ACTIVITIES[c.activity]+' · '+c.current_service_date+' · 当前应付 '+c.current_amount+' 元':'原记录当前不在选项中';}return'<div class="form-item"><label>'+esc(label)+'</label><span>'+esc(display)+'</span>'+(!locked?'<button type="button" class="btn gray" data-case-picker="'+esc(type)+'" data-path="'+esc(path)+'">选择</button>':'')+'</div>';}
 function evidenceForm(s,prefix,labels){return'<details><summary>逐项核对说明与凭证</summary><p class="modal-intro">填写实际依据；未知事实不因填写说明变成“是”。也可填写一段完整说明，再明确应用到本次已核实的事实。</p><div class="form-grid"><div class="form-item"><label>本次共同核对说明</label><textarea rows="3" maxlength="2000" data-case-bulk-note="'+esc(prefix)+'"></textarea></div><div class="form-item"><label>共同凭证号（选填）</label><input maxlength="500" data-case-bulk-ref="'+esc(prefix)+'"></div></div><button class="btn gray" type="button" data-case-bulk="'+esc(prefix)+'">应用到已填写的事实</button><div class="form-grid">'+Object.entries(labels).map(([key,label])=>proofFields(s,prefix+'evidence_notes.'+key+'.',label)).join('')+'</div></details>';}
 function developmentForm(s,prefix='',fixed=false){const d=get(s.draft,prefix.slice(0,-1))||s.draft;return'<div class="form-grid">'+sel(s,prefix+'activity','开发方式',{SOLO_DEVELOPMENT:'独立开发',JOINT_DEVELOPMENT:'合作开发'},fixed)+input(s,prefix+'service_date','实际业务日期','date',null,fixed&&prefix!=='')+input(s,prefix+'completed_on','成果完成日期','date')+pickerButton(s,prefix+'lead_teacher_id','开发主负责人','teacher',fixed)+'</div><div class="form-grid">'+input(s,prefix+'deliverable_code','原台账成果编号','text',null,fixed)+input(s,prefix+'deliverable_version','原台账成果版本','text',null,fixed)+(!fixed?'<div class="form-item"><label>已有成果记录</label><button type="button" class="btn gray" data-case-picker="deliverable" data-path="'+esc(prefix)+'">从已有事项选择</button></div>':'')+'</div><p class="modal-intro">按真实台账填写成果编号与版本；没有可靠编号时保留草稿，不另造编号重复申报。</p><details open><summary>资格与计酬依据</summary><div class="form-grid">'+sel(s,prefix+'grade','已核实的本人等级',GRADES)+input(s,prefix+'appointed_on','实际获聘日期','date')+input(s,prefix+'payable_hours','开发计酬课时')+input(s,prefix+'repetition_percent','成果重复率（%）')+Object.entries(devTruth).slice(0,5).map(([k,l])=>tri(s,prefix+k,l)).join('')+'</div></details><details open><summary>开发路径与实际完成情况</summary><div class="form-grid">'+sel(s,prefix+'development_path','开发路径',{CUSTOMER_REQUESTED:'客户委托',SELF_INITIATED:'自主开发'})+Object.entries(devTruth).slice(5).map(([k,l])=>tri(s,prefix+k,l)).join('')+input(s,prefix+'customer_acceptance_on','实际客户验收日期','date')+input(s,prefix+'annual_review_on','实际年度评审日期','date')+input(s,prefix+'company_approval_on','实际公司核准日期','date')+'</div></details>'+(d.activity==='JOINT_DEVELOPMENT'?'<details open><summary>合作开发明确分额</summary><p class="modal-intro">先保存资格资料可查看条件预览。请逐人填写已商定的金额，合计须等于服务器给出的总池；此处不会自动均分或补尾差。</p><div class="form-grid">'+sel(s,prefix+'joint_reference_grade','研发负责人本次采用的计费等级',{LECTURER:GRADES.LECTURER,...(d.grade&&d.grade!=='LECTURER'?{[d.grade]:GRADES[d.grade]}:{})})+'</div><div data-case-allocations></div>'+(!fixed?'<button type="button" class="btn gray" data-case-add-allocation="'+esc(prefix)+'">添加合作成员</button>':'')+'</details>':'')+evidenceForm(s,prefix,devEvidence);}
 function hoursForm(s,prefix,teaching=false){const fields=teaching?{estimated:'预计课时',planned:'计划课时',actual_minutes:'实际授课分钟',payable:'计酬课时'}:{ESTIMATED:'预计课时',PLANNED:'计划课时',ACTUAL:'实际课时',PAYABLE:'计酬课时'};return'<p class="modal-intro">四类课时分别核对；未知留空，0 须明确填写。'+(teaching?'实际分钟与课时分别登记，不按计划反推。':'')+'</p><div class="form-grid">'+Object.entries(fields).map(([k,l])=>input(s,prefix+k,l)).join('')+'</div>';}
 function migrationForm(s){return'<div class="form-grid">'+input(s,'legacy_source_code','真实旧系统 / 原单据名称或编号')+input(s,'legacy_rule_code','原课酬规则名称或编号')+input(s,'service_date','实际业务日期','date')+pickerButton(s,'teacher_id','原收款教师','teacher')+input(s,'amount','原已核准应付总额（元）')+'</div><p class="modal-intro">保留原制度下已核准的应付金额，不套用现行费率。</p><div class="form-grid">'+proofFields(s,'source_','原始台账核对')+proofFields(s,'original_approval_','原审批依据核对')+'</div>'+hoursForm(s,'hours.')+'<div class="form-item"><label>是否同时登记历史实际付款</label><select data-case-history-toggle><option value="no"'+(!s.draft.historical_payment?' selected':'')+'>本次不登记历史付款</option><option value="yes"'+(s.draft.historical_payment?' selected':'')+'>有真实历史付款，填写核对资料</option></select></div>'+(s.draft.historical_payment?'<div class="form-grid">'+input(s,'historical_payment.payment_date','历史实际付款日期','date')+input(s,'historical_payment.amount','历史实付金额（元）')+proofFields(s,'historical_payment.','原付款核对')+'</div><p class="inline-note">确认时会登记这笔历史实付；确认人还须有付款登记权限。请勿填写计划付款。</p>':'');}
 function teachingForm(s){return'<div class="form-grid">'+sel(s,'claim.grade','已核实讲师等级',GRADES)+sel(s,'claim.day_type','实际授课日别',DAYS)+input(s,'claim.appointed_on','实际获聘日期','date')+Object.entries(devTruth).slice(0,4).map(([k,l])=>tri(s,'claim.'+k,l)).join('')+'</div>'+hoursForm(s,'hours.',true)+evidenceForm(s,'claim.',teachEvidence);}
 function adjustmentForm(s){const d=s.draft;return'<div class="form-grid">'+pickerButton(s,'chain_code','要更正的已确认记录','chain')+'</div><p class="modal-intro">更正后保留原实付，只追加应付差额。跨日期会分别登记原日冲回和新日应付；有已付款的记录也从当前余额补付或退款。</p><div class="form-item"><label>本次处理</label><select data-case-cancel-toggle><option value="false"'+(!d.cancellation?' selected':'')+'>更正资料和新的应付总额</option><option value="true"'+(d.cancellation?' selected':'')+'>冲销该业务的全部应付</option></select></div>'+(d._group?.length>1?'<p class="inline-note">这是合作开发整组业务，将一并核对 '+d._group.length+' 名成员的当前账目。</p>':'')+'<div class="form-grid">'+proofFields(s,'reason_','本次更正原因')+proofFields(s,'evidence_','本次实际核对')+'</div>'+(d.cancellation?'<p class="inline-note">冲销将原应付核准为 0；已付金额保留，形成的待退款须按实际退款另行登记。</p>':!d.chain_code?'<p>请先选择原业务。</p>':'<div class="form-grid">'+input(s,'service_date','更正后的实际业务日期','date')+'</div>'+(d._activity==='TEACHING'?teachingForm(s):d._activity==='LEGACY'?'<div class="form-grid">'+input(s,'legacy_rule_code','原课酬规则','text',null,true)+input(s,'amount','更正后的总应付（元）')+proofFields(s,'source_','原始台账核对')+proofFields(s,'original_approval_','原审批依据核对')+'</div>'+hoursForm(s,'legacy_hours.'):d.development?developmentForm(s,'development.',true):'<p class="inline-note">未找到可完整核对的原开发事项，请重新读取。</p>'));}
 function renderEditor(s){if(!ensure(s))return;let html=s.kind==='DEVELOPMENT'?developmentForm(s):s.kind==='MIGRATION'?migrationForm(s):s.kind==='ADJUSTMENT'?adjustmentForm(s):'<div class="form-grid">'+pickerButton(s,'dispatch_id','本次不计课酬的授课','dispatch')+proofFields(s,'reason_','免付原因')+proofFields(s,'evidence_','实际授课及免付核对')+'</div><p class="inline-note">须已核验实际授课且尚无财务账目。确认后保留实际授课、明确不计课酬，不创建虚假付款。</p>';n(s,'fields').innerHTML=html;for(const f of s.mask.querySelectorAll('[data-case-field]')){const path=f.dataset.caseField;f.value=get(s.draft,path)??'';f.oninput=f.onchange=()=>{if(!ensure(s)||s.busy||s.pending||!editable(s)||f.disabled)return;set(s.draft,path,f.value===''?null:f.value);s.action=null;n(s,'action').innerHTML='';if(path.endsWith('activity')||path.endsWith('grade'))renderEditor(s);controls(s);};}for(const b of s.mask.querySelectorAll('[data-case-picker]'))b.onclick=()=>startPicker(s,b.dataset.casePicker,b.dataset.path);for(const b of s.mask.querySelectorAll('[data-case-bulk]'))b.onclick=()=>applyBulk(s,b.dataset.caseBulk);const h=n(s,'history-toggle');if(h)h.onchange=()=>{if(!editable(s)||s.busy||s.pending)return;s.draft.historical_payment=h.value==='yes'?{payment_date:null,amount:null,note:null,reference:null}:null;renderEditor(s);};const c=n(s,'cancel-toggle');if(c)c.onchange=()=>{if(!editable(s)||s.busy||s.pending)return;s.draft.cancellation=c.value==='true';renderEditor(s);};for(const b of s.mask.querySelectorAll('[data-case-add-allocation]'))b.onclick=()=>startPicker(s,'allocation',b.dataset.caseAddAllocation);for(const f of s.mask.querySelectorAll('[data-case-bulk-note],[data-case-bulk-ref]')){const prefix=f.dataset.caseBulkNote??f.dataset.caseBulkRef,key=f.hasAttribute('data-case-bulk-note')?'note':'reference';s.bulkNotes??={};s.bulkNotes[prefix]??={note:'',reference:''};f.value=s.bulkNotes[prefix][key];f.oninput=()=>{if(!editable(s)||s.busy||s.pending)return;s.bulkNotes[prefix][key]=f.value;controls(s);};}renderAllocations(s);controls(s);}
 function renderAllocations(s){const area=n(s,'allocations');if(!area)return;const prefix=s.kind==='ADJUSTMENT'?'development.':'',d=prefix?s.draft.development:s.draft,rows=d?.allocations??[];s.allocPage=Math.min(s.allocPage||0,Math.max(0,Math.ceil(rows.length/20)-1));area.innerHTML='<table class="tbl"><thead><tr><th scope="col">成员</th><th scope="col">明确金额（元）</th><th scope="col">操作</th></tr></thead><tbody>'+rows.slice(s.allocPage*20,s.allocPage*20+20).map((r,i)=>{const index=s.allocPage*20+i;return'<tr><td data-label="成员">'+esc(teacherLabel(r.teacher_id,s.options,s.teachers))+'</td><td data-label="明确金额"><div class="form-item"><input data-case-allocation="'+index+'" value="'+esc(r.amount??'')+'"></div></td><td data-label="操作">'+(s.kind!=='ADJUSTMENT'?'<button type="button" class="btn gray" data-case-remove-allocation="'+index+'">移除新填成员</button>':'原成员保留')+'</td></tr>';}).join('')+'</tbody></table><div class="toolbar"><button class="btn gray" type="button" data-case-alloc-prev>上一页</button><span>共 '+rows.length+' 人</span><button class="btn gray" type="button" data-case-alloc-next>下一页</button></div>';for(const f of s.mask.querySelectorAll('[data-case-allocation]'))f.oninput=()=>{if(!editable(s)||s.busy||s.pending)return;rows[Number(f.dataset.caseAllocation)].amount=f.value||null;controls(s);};for(const b of s.mask.querySelectorAll('[data-case-remove-allocation]'))b.onclick=()=>{if(!editable(s)||s.busy||s.pending||s.kind==='ADJUSTMENT')return;rows.splice(Number(b.dataset.caseRemoveAllocation),1);renderAllocations(s);controls(s);};n(s,'alloc-prev').disabled=s.allocPage===0;n(s,'alloc-next').disabled=(s.allocPage+1)*20>=rows.length;n(s,'alloc-prev').onclick=()=>{if(s.busy||s.pending||s.allocPage===0)return;s.allocPage--;renderAllocations(s);controls(s);};n(s,'alloc-next').onclick=()=>{if(s.busy||s.pending||(s.allocPage+1)*20>=rows.length)return;s.allocPage++;renderAllocations(s);controls(s);};}
 function applyBulk(s,prefix){if(!ensure(s)||!editable(s)||s.busy||s.pending)return;const note=s.mask.querySelector('[data-case-bulk-note="'+prefix+'"]')?.value.trim(),reference=s.mask.querySelector('[data-case-bulk-ref="'+prefix+'"]')?.value.trim();try{const p=validProof(note,reference,true),d=prefix?get(s.draft,prefix.slice(0,-1)):s.draft,labels=prefix==='claim.'?teachEvidence:devEvidence;for(const k of Object.keys(labels)){const field={appointment:'appointed_on',applicability:'service_date_applicable',repetition:'repetition_percent',completion:'completed_on',deliverable:'deliverable_code',allocation:'allocations',joint_basis:'joint_reference_grade'}[k]||k,v=d[field];if(v!==null&&v!==undefined&&v!=='UNKNOWN'&&(!Array.isArray(v)||v.length))d.evidence_notes[k]=clone(p);}if(s.bulkNotes)delete s.bulkNotes[prefix];renderEditor(s);toast(s,'已将实际说明用于本次已填写的事实，请逐项核对后保存。');}catch(e){toast(s,e.message);}}
 function startPicker(s,type,path){if(!ensure(s)||s.busy||s.pending||(type!=='payment'&&!editable(s)))return;s.picker={type,path,page:0,search:''};renderPicker(s);}
 function pickerRows(s){const p=s.picker;let rows;if(p.type==='teacher'||p.type==='allocation')rows=s.teachers.map(t=>({key:String(t.id),label:teacherLabel(t.id,s.options,s.teachers),raw:t}));else if(p.type==='dispatch')rows=s.options.dispatches.map(d=>({key:String(d.dispatch_id),label:d.teacher_name+' · '+(d.subject||'未填课题')+' · '+(d.teach_date||'日期待定')+' · '+d.status,raw:d}));else if(p.type==='deliverable')rows=s.options.deliverables.map(d=>({key:d.case_code,label:d.deliverable_code+' · 版本 '+d.deliverable_version+' · '+STATES[d.state]+' · 项目 #'+d.project_id,raw:d}));else rows=(p.type==='payment'?s.snapshot.financial.map(f=>f.chain).filter(c=>minor(c.balance)!==0n):s.options.financial_chains).map(c=>({key:c.chain_code,label:teacherLabel(c.teacher_id,s.options,s.teachers)+' · '+ACTIVITIES[c.activity]+' · '+c.current_service_date+' · 应付 '+c.current_amount+' 元 · 余额 '+c.balance+' 元',raw:c}));return rows.filter(r=>r.label.toLocaleLowerCase().includes(p.search.toLocaleLowerCase()));}
 function renderPicker(s){if(!s.picker||!owns(s))return;const p=s.picker,rows=pickerRows(s);p.page=Math.min(p.page,Math.max(0,Math.ceil(rows.length/20)-1));n(s,'picker').innerHTML='<div class="panel"><div class="form-item"><label>查找'+({teacher:'教师档案',allocation:'合作成员',dispatch:'授课',chain:'已确认业务',payment:'当前付款 / 退款记录',deliverable:'已有成果'})[p.type]+'</label><input data-case-picker-search value="'+esc(p.search)+'"></div><div data-case-picker-results>'+rows.slice(p.page*20,p.page*20+20).map(r=>'<p><button type="button" class="btn gray" style="white-space:normal;text-align:left" data-case-pick="'+esc(r.key)+'">'+esc(r.label)+'</button></p>').join('')+(!rows.length?'<p>没有匹配选项。请核对原师资或业务资料，不能手填内部标识。</p>':'')+'</div><div class="toolbar"><button type="button" class="btn gray" data-case-picker-prev>上一页</button><span>共 '+rows.length+' 项</span><button type="button" class="btn gray" data-case-picker-next>下一页</button><button type="button" class="btn gray" data-case-picker-close>收起选择</button></div></div>';n(s,'picker-search').oninput=e=>{if(!owns(s)||s.busy||s.pending)return;p.search=e?.target?.value??n(s,'picker-search').value;p.page=0;renderPicker(s);n(s,'picker-search').focus?.();};n(s,'picker-prev').disabled=p.page===0;n(s,'picker-next').disabled=(p.page+1)*20>=rows.length;n(s,'picker-prev').onclick=()=>{if(s.busy||s.pending||p.page===0)return;p.page--;renderPicker(s);};n(s,'picker-next').onclick=()=>{if(s.busy||s.pending||(p.page+1)*20>=rows.length)return;p.page++;renderPicker(s);};n(s,'picker-close').onclick=()=>{s.picker=null;n(s,'picker').innerHTML='';};for(const b of s.mask.querySelectorAll('[data-case-pick]'))b.onclick=()=>{if(!ensure(s)||s.busy||s.pending)return;const row=rows.find(x=>x.key===b.dataset.casePick);if(!row)return;try{if(p.type==='payment'){s.actionData.chain_code=row.raw.chain_code;renderAction(s);}else if(p.type==='allocation'){const d=p.path?get(s.draft,p.path.slice(0,-1)):s.draft;if(d.allocations.some(x=>x.teacher_id===row.raw.id))throw Error('该成员已在分配表中。');if(d.allocations.length>=100)throw Error('合作成员最多 100 人。');d.allocations.push({teacher_id:row.raw.id,amount:null});renderAllocations(s);}else if(p.type==='chain'){selectChain(s,row.raw);renderEditor(s);}else if(p.type==='deliverable'){const prefix=p.path;set(s.draft,prefix+'deliverable_code',row.raw.deliverable_code);set(s.draft,prefix+'deliverable_version',row.raw.deliverable_version);renderEditor(s);toast(s,'已引用真实成果编号与版本；同一版本不能重复计发，请核对当前事项。');}else{set(s.draft,p.path,p.type==='teacher'?row.raw.id:row.raw.dispatch_id);renderEditor(s);}s.picker=null;n(s,'picker').innerHTML='';controls(s);}catch(e){toast(s,e.message);}};controls(s);}
